  let bestDist = maxDist;
  for (const car of world.cars) {
    if (car.wrecked) continue;
    const dist = Math.hypot(car.x - world.player.x, car.z - world.player.z);
    if (dist < bestDist) {
      bestDist = dist;
      best = car;
